  spawn(bossIndex=null){const a=this.random()*Math.PI*2,dist=550+this.random()*150,t=this.time/600,stage=this.stage.id;let type=this.random()<.18?'runner':this.random()<.18?'tank':'walker';if(this.time>75&&this.random()<.12)type='spitter';const boss=bossIndex!==null;if(boss)type='boss';const hp=boss?5*(2800+bossIndex*1700)*(1+(stage-1)*.8)*(1+Math.max(0,t-1)*.6):1.5*(type==='tank'?240:85)*(1+t*2.8)*(1+(stage-1)*.45);const e={id:++this.uid,x:clamp(this.player.x+Math.cos(a)*dist,30,2570),y:clamp(this.player.y+Math.sin(a)*dist,30,1770),type,boss,bossIndex,name:boss?this.stage.bosses[bossIndex%5===4?1:0]+(bossIndex%5===4?' · 지배자':' · '+(bossIndex+1)):'',hp,maxHp:hp,r:boss?40:type==='tank'?21:type==='runner'?11:15,speed:boss?90+Math.min(bossIndex,12)*7:type==='runner'?125:type==='tank'?40:type==='spitter'?56:65,damage:(boss?45+bossIndex*6:type==='tank'?28:18)*(1+(stage-1)*.3)*(1+t*.5),attack:2+this.random()*2,slow:0,hit:0,dead:false};e.speed*=1+(stage-1)*.1;this.enemies.push(e);if(boss)this.emit('boss',{name:e.name,index:bossIndex});return e;}
