    this.attack(dt);for(const e of this.enemies){if(e.dead)continue;e.hit=Math.max(0,e.hit-dt);e.slow=Math.max(0,e.slow-dt);const a=Math.atan2(p.y-e.y,p.x-e.x),d=distance(e,p);if(this.frozen===0||e.boss){const v=e.speed*(e.slow>0?.38:1)*(e.type==='spitter'&&d<320?-.4:1);e.x=clamp(e.x+Math.cos(a)*v*dt,20,2580);e.y=clamp(e.y+Math.sin(a)*v*dt,20,1780);e.attack-=dt;if((e.boss||e.type==='spitter')&&e.attack<=0){const count=e.boss?12+Math.min(e.bossIndex||0,10)*2:1;for(let i=0;i<count;i++){const ang=e.boss?i/count*Math.PI*2+this.time*.3:a;this.hostile.push({x:e.x,y:e.y,vx:Math.cos(ang)*150,vy:Math.sin(ang)*150,r:e.boss?7:5,life:6,damage:e.damage*.75,bossOwned:e.boss});}e.attack=e.boss?1.9:2.8;}}if(d<e.r+13&&(this.frozen===0||e.boss))this.damage(e.damage);}
