    for(const b of this.hostile){if(this.frozen===0||b.bossOwned){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(distance(p,b)<b.r+12){this.damage(b.damage);b.life=0;}}}
    for(const f of this.fields){f.life-=dt;f.tick-=dt;for(const e of this.enemies){const d=distance(e,f);if(d<f.r){if(this.frozen===0&&!e.boss){const a=Math.atan2(f.y-e.y,f.x-e.x);e.x+=Math.cos(a)*80*dt;e.y+=Math.sin(a)*80*dt;}if(f.tick<=0)this.hit(e,f.damage*.5);}}if(f.tick<=0)f.tick=.5;}
    let gainedXp=0;for(const d of this.drops){d.life-=dt;const dist=distance(p,d);if(dist<(this.stats.pickup)){const a=Math.atan2(p.y-d.y,p.x-d.x);d.x+=Math.cos(a)*520*dt;d.y+=Math.sin(a)*520*dt;if(dist<24){d.life=0;if(d.type==='xp')gainedXp+=d.value;else if(d.type==='item')this.addItem();else p.hp=Math.min(this.stats.hp,p.hp+25);}}}
    for(const fx of this.effects)fx.life-=dt;for(const n of this.numbers){n.life-=dt;n.y-=25*dt;}this.enemies=this.enemies.filter(e=>!e.dead);this.bullets=this.bullets.filter(e=>e.life>0);this.hostile=this.hostile.filter(e=>e.life>0);this.drops=this.drops.filter(e=>e.life>0).slice(-500);this.effects=this.effects.filter(e=>e.life>0).slice(-100);this.numbers=this.numbers.filter(e=>e.life>0);this.fields=this.fields.filter(e=>e.life>0);if(this.state==='ended')return;if(this.mode!=='endless'&&this.time>=600&&this.bossKills>=5){this.end('clear');return;}if(gainedXp)this.gainXp(gainedXp);
